@app.route('/write_temp', methods=['POST'])
def write_results():
    try:
        data = request.get_json()
        results = data['results']
    except KeyError:
        return jsonify({"error": "Missing 'results' key"}), 400
    except ValueError:
        return jsonify({"error": "Invalid JSON format"}), 400

    sanitized_results = werkzeug.utils.safe_str(results)

    if len(sanitized_results.encode('utf-8')) > max_file_size:
        return jsonify({"error": "File size exceeds limit"}), 400

    try:
        with tempfile.NamedTemporaryFile(delete=False, mode='w', encoding='utf-8') as temp_file:
            temp_file.write(sanitized_results)
            temp_file_path = temp_file.name
    except OSError:
        return jsonify({"error": "Failed to create temporary file"}), 500

    return jsonify({"temp_file_path": temp_file_path}), 200

