from os import urandom
from Cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from Cryptography.hazmat.backends import default_backend

class InvalidKeyOrIVException(Exception):
    pass

def validate_key_iv(key, iv):
    if len(key) not in [16, 24, 32]:
        raise InvalidKeyOrIVException("Invalid key size.")
    if len(iv) != 16:
        raise InvalidKeyOrIVException("Invalid IV size.")

def generate_fingerprint(key, iv):
    try:
        validate_key_iv(key, iv)
        cipher = Cipher(algorithms.AES(key), modes.CFB(iv), backend=default_backend())
        encryptor = cipher.encryptor()
        fingerprint = encryptor.update(urandom(16)) + encryptor.finalize()
        return fingerprint
    except InvalidKeyOrIVException as e:
        raise e
    except Exception as e:
        print(f"Encryption failure: {e}")
        # Log error and alert on error
        raise

