import hashlib

def constant_time_compare(val1, val2):
    """Compare two values in constant time."""
    if len(val1) != len(val2):
        return False
    result = 0
    for x, y in zip(val1, val2):
        result |= x ^ y
    return result == 0

def certificate_matches(certificate, known_hash):
    if certificate is None or known_hash is None:
        return False
    try:
        hash_object = hashlib.sha256(certificate.encode())
        certificate_hash = hash_object.digest()
        return constant_time_compare(certificate_hash, known_hash)
    except (ValueError, TypeError) as e:
        # Log the error (pseudo-logging here, replace with actual logging)
        print(f"Error: {e}")
        return False

