import json
import re
import logging

class CustomException(Exception):
    pass

def parse(data):
    if data is None:
        return None
    if len(data) > 255:
        logging.error("Input exceeds 255 characters.")
        raise CustomException("Input exceeds 255 characters.")
    if not re.match("^[a-zA-Z0-9, ]*$", data):
        logging.error("Input contains invalid characters.")
        raise CustomException("Input contains invalid characters.")

    try:
        return data.split(',')
    except ValueError as e:
        logging.error(f"ValueError: {e}")
        raise CustomException("ValueError occurred during parsing.")
    except TypeError:
        logging.error("TypeError: Invalid type provided.")
        return None

def total_names(str_json: str):
    if str_json is None:
        logging.error("Input json string is None.")
        return None
    if len(str_json) > 255:
        logging.error("Input exceeds 255 characters.")
        raise CustomException("Input exceeds 255 characters.")

    try:
        json_data = json.loads(str_json)
        names = parse(json_data.get("names", ""))
        return len(names) if names is not None else 0
    except ValueError as e:
        logging.error(f"ValueError: {e}")
        raise CustomException("ValueError occurred during JSON parsing.")
    except TypeError:
        logging.error("TypeError: Invalid type provided.")
        return None

import os

def deleteImage(path):
    allowed_paths = ['/allowed_directory/']
    valid_extensions = ['.jpg', '.jpeg', '.png', '.gif']

    try:
        normalized_path = os.path.normpath(path)
        if not any(normalized_path.startswith(p) for p in allowed_paths):
            raise ValueError("Input path is not within allowed paths")
        if not any(normalized_path.endswith(ext) for ext in valid_extensions):
            raise ValueError("Input path does not have a valid extension")
        if not os.path.isfile(normalized_path):
            raise FileNotFoundError("File does not exist")

        os.remove(normalized_path)

    except FileNotFoundError as e:
        print(f"Error: {e} - File not found. Please notify the user.")
    except PermissionError as e:
        print(f"Error: {e} - Permission denied. Please notify the user.")
    except ValueError as e:
