        log_error("Input data must be of type string.")
        return None
    if not any(file_path.endswith(ext) for ext in ALLOWED_EXTENSIONS):
        log_error("Invalid file extension.")
        return None
    try:
        with open(file_path, 'w') as f:
            json.dump(data, f)
    except FileNotFoundError:
