app = Flask(__name__)
ALLOWED_EXTENSIONS = {'png', 'jpg', 'jpeg', 'gif'}
MAX_FILE_SIZE = 5 * 1024 * 1024  # 5 MB
ALLOWED_PATH = os.path.abspath('./assets/img')

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

@app.route('/img/upload', methods=['POST'])
def upload_img():
    try:
        if 'filename' not in request.form or 'img' not in request.form:
            raise ValueError("Missing filename or image data.")

        filename = request.form['filename']
        img_data = request.form['img']

        if not allowed_file(filename):
            return Response("Invalid file extension.", status=400)

        img_size = len(base64.b64decode(img_data))
        if img_size > MAX_FILE_SIZE:
            return Response("File size exceeds limit.", status=400)

        file_path = os.path.join(ALLOWED_PATH, filename + '.png')
        if not file_path.startswith(ALLOWED_PATH):
            return Response("Invalid file path.", status=400)

        with open(file_path, 'wb') as f:
            f.write(base64.b64decode(img_data))

        return Response(status=200)

    except FileNotFoundError:
        return Response(status=404)
    except ValueError as ve:
        return Response(str(ve), status=400)
    except Exception as e:
        app.logger.error(e)
        return Response(status=500)

