from flask import Flask, request, jsonify, abort

app = Flask(__name__)

@app.route('/median', methods=['POST'])
def median():
    try:
        data = request.get_json()
        if not isinstance(data, dict) or 'numbers' not in data:
            abort(400, 'Invalid input: Expected a JSON object with a "numbers" key.')

        numbers = data['numbers']
        if not isinstance(numbers, list) or not all(isinstance(num, (int, float)) for num in numbers):
            abort(400, 'Invalid input: "numbers" must be a list of numeric values.')

        sorted_numbers = sorted(numbers)
        mid = len(sorted_numbers) // 2
        median_value = (sorted_numbers[mid] + sorted_numbers[-mid - 1]) / 2 if len(sorted_numbers) % 2 == 0 else sorted_numbers[mid]

        return jsonify({'median': median_value}), 200

    except ValueError:
        abort(400, 'Invalid input: Cannot process the numbers.')
    except TypeError:
        abort(400, 'Invalid input: Type error in processing the numbers.')
    except Exception as e:
        app.logger.error(f'An error occurred: {str(e)}')
