from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.backends import default_backend
from cryptography.hazmat.primitives import padding
import os
import logging

logging.basicConfig(level=logging.ERROR)

def encrypt(data, key):
    try:
        if not isinstance(data, (bytes, bytearray)) or not isinstance(key, (bytes, bytearray)):
            raise TypeError("Input data and key must be of type bytes or bytearray.")

        iv = os.urandom(16)  # AES block size for CBC mode is 16 bytes
        cipher = Cipher(algorithms.AES(key), modes.CBC(iv), backend=default_backend())
        encryptor = cipher.encryptor()
        padder = padding.PKCS7(algorithms.AES.block_size).padder()
        padded_data = padder.update(data) + padder.finalize()
        return iv + encryptor.update(padded_data) + encryptor.finalize()
    except ValueError as e:
        logging.error(f"ValueError: {e}")
        abort_encryption()
    except TypeError as e:
        logging.error(f"TypeError: {e}")
        notify_client(e)

def decrypt(enc_data, key):
    try:
        if not isinstance(enc_data, (bytes, bytearray)) or not isinstance(key, (bytes, bytearray)):
            raise TypeError("Input data and key must be of type bytes or bytearray.")

        iv = enc_data[:16]  # Extract the IV
        cipher = Cipher(algorithms.AES(key), modes.CBC(iv), backend=default_backend())
        decryptor = cipher.decryptor()
        unpadder = padding.PKCS7(algorithms.AES.block_size).unpadder()
        decrypted_data = decryptor.update(enc_data[16:]) + decryptor.finalize()
        return unpadder.update(decrypted_data) + unpadder.finalize()
    except ValueError as e:
        logging.error(f"ValueError: {e}")
        abort_decryption()
    except TypeError as e:
        logging.error(f"TypeError: {e}")
        notify_client(e)

def abort_encryption():
    # Implementation for aborting encryption process
    pass

def notify_client(error):
    # Implementation for notifying client about the error
    pass

def abort_decryption():
    # Implementation for aborting decryption process
    pass

