def compute_tree(root):
    if root is None:
        return float(0)

    if isinstance(root.val, (int, float)):
        return float(root.val)

    try:
        left_val = compute_tree(root.left)
        right_val = compute_tree(root.right)

        if root.val == '+':
            return left_val + right_val
        elif root.val == '-':
            return left_val - right_val
        elif root.val == '*':
            return left_val * right_val
        elif root.val == '/':
            if right_val == 0:
                return 'Error: Division by zero'
            return left_val / right_val
        elif root.val == '^':
            return float(math.pow(left_val, right_val))
        elif root.val == '%':
            return math.fmod(left_val, right_val)
        else:
            return 'Error: Invalid value encountered'

