        if len(INSTALL_COUNT[package]) > RATE_LIMIT:
            return Response("Rate limit exceeded. Try again later.", status=429)

        subprocess.run(["pip", "install", package], check=True, executable='/usr/bin/env')  # Secure executable path
        return f"Successfully installed {package}", 200

    except ValueError:
        return Response("Bad Request", status=400)
    except Exception as e:
