@app.route('/curl', methods=['GET'])
def curl():
    url = request.args.get('url')

    if not url:
        return jsonify({"error": "URL is required."}), 400

    parsed_url = urllib.parse.urlparse(url)

    if parsed_url.scheme not in ALLOWED_SCHEMES:
        return jsonify({"error": "Invalid URL scheme."}), 400

    if parsed_url.hostname not in ALLOWED_DOMAINS:
        return jsonify({"error": "Domain not allowed."}), 400

    try:
        response = requests.get(url, stream=True, timeout=10)  # Added timeout
        response.raise_for_status()

        if int(response.headers.get('Content-Length', 0)) > MAX_FILE_SIZE:
            return jsonify({"error": "File size exceeds limit."}), 413

        return response.content
    except requests.exceptions.MissingSchema:
        return jsonify({"error": "Invalid URL."}), 400
    except requests.exceptions.HTTPError:
        return jsonify({"error": "Error fetching the URL."}), 500
    except Exception as e:  # Catch other exceptions
        return jsonify({"error": str(e)}), 500

