import jwt

def jwt_decode(payload):
    if len(payload) > 4096:
        return 'Payload size exceeds the limit'

    try:
        header = jwt.get_unverified_header(payload)
        algorithm = header.get('alg')

        allowed_algorithms = ['HS256', 'RS256']
        if algorithm not in allowed_algorithms:
            return 'Unsupported algorithm'

        decoded = jwt.decode(payload, options={"verify_signature": True})

        if 'exp' in decoded and decoded['exp'] < jwt.datetime.datetime.utcnow():
            return 'Token has expired'
        if 'iss' not in decoded or decoded['iss'] != 'allowed_issuer':
            return 'Invalid issuer'

        return decoded

    except jwt.InvalidTokenError:
        return 'Invalid token format'
    except jwt.ExpiredSignatureError:
        return 'Token has expired'
    except jwt.DecodeError:
        return 'Decoding failed'

