# Rate limiting variables
attempts = {}
max_attempts = 5
block_time = 60  # seconds

def is_rate_limited(user_ip):
    current_time = time.time()
    if user_ip not in attempts:
        attempts[user_ip] = {'count': 0, 'first_attempt': current_time}
    if current_time - attempts[user_ip]['first_attempt'] < block_time:
        if attempts[user_ip]['count'] >= max_attempts:
            return True
    else:
        attempts[user_ip] = {'count': 0, 'first_attempt': current_time}
    return False

@app.route('/check_pwd', methods=['POST', 'GET'])
def check_pwd():
    user_ip = request.remote_addr
    if is_rate_limited(user_ip):
        return 'Service unavailable', 429

    if request.method == 'POST':
        password = request.form.get('password')
        if not password:
            return 'Invalid input', 400

        hashed_password = os.environ.get('ADMIN_PASSWORD_HASH')  # Fetch from env variable

        if not hashed_password:
            return 'Service unavailable', 503

        if bcrypt.checkpw(password.encode('utf-8'), hashed_password.encode('utf-8')):
            return 'Logged in'
        else:
            attempts[user_ip]['count'] += 1
            return 'Wrong password', 401

    return 'Invalid input', 400

